-- C0 exact release probe: no physical action; every synthetic row rolls back.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.prove(result text)returns void language plpgsql as $$begin
 if result not like 'ok %'then raise exception 'Hosted controlled draft proof failed: %',result;end if;
 perform set_config('lrv.controlled_draft_checks',(coalesce(nullif(current_setting('lrv.controlled_draft_checks',true),''),'0')::integer+1)::text,true);
end $$;
create temp table controlled_fixture(key text primary key,value jsonb);grant all on controlled_fixture to authenticated;
insert into controlled_fixture select key,to_jsonb(gen_random_uuid())from unnest(array['actor','session','entry','product','action','missing_action'])key;
create function pg_temp.id(key text)returns uuid language sql as $$select(value#>>'{}')::uuid from controlled_fixture where controlled_fixture.key=$1$$;
insert into controlled_fixture values('baseline',jsonb_build_object('stock',(select count(*)from inventory_movements),'outbox',(select count(*)from communication_outbox),'invoices',(select count(*)from billing_invoices),'payments',(select count(*)from payment_provider_profiles)));
insert into auth.users(id,email,raw_user_meta_data)values(pg_temp.id('actor'),'synthetic-controlled-'||pg_temp.id('actor')||'@example.test','{}');
update profiles set is_active=true,full_name='Synthetic rollback draft reviewer'where id=pg_temp.id('actor');insert into user_roles(user_id,role)values(pg_temp.id('actor'),'DVM')on conflict do nothing;
insert into auth.sessions(id,user_id,created_at,updated_at)values(pg_temp.id('session'),pg_temp.id('actor'),now(),now());
select pg_temp.prove(ok(relrowsecurity and not has_table_privilege('anon',oid,'SELECT')and not has_table_privilege('authenticated',oid,'SELECT')and not has_table_privilege('service_role',oid,'INSERT'),relname||' private RLS'))from pg_class where relnamespace='public'::regnamespace and relname in('controlled_draft_entries','controlled_draft_versions','controlled_draft_reviews','controlled_draft_actions','controlled_draft_cancellations');
select pg_temp.prove(ok(not has_function_privilege('anon',oid,'EXECUTE')and not has_function_privilege('service_role',oid,'EXECUTE')and has_function_privilege('authenticated',oid,'EXECUTE'),proname||' guarded RPC'))from pg_proc where pronamespace='public'::regnamespace and proname in('prepare_controlled_draft_review','execute_controlled_draft_review','read_controlled_draft_review','cancel_controlled_draft_review','list_controlled_drafts','read_controlled_draft');
select pg_temp.prove(ok(not exists(select 1 from pg_proc where pronamespace='public'::regnamespace and proname like 'controlled_draft_%'and(has_function_privilege('authenticated',oid,'EXECUTE')or has_function_privilege('service_role',oid,'EXECUTE'))),'Private draft helpers remain owner only'));
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',pg_temp.id('actor'),'session_id',pg_temp.id('session'))::text,true);
set local role authenticated;
select create_inventory_product(pg_temp.id('product'),'Synthetic rollback draft medication','medication','Synthetic maker','mL',100);
insert into controlled_fixture values('request',jsonb_build_object('id',pg_temp.id('entry'),'expected_version',null,'definition',jsonb_build_object('product_id',pg_temp.id('product'),'product_version',1,'stock_unit','mL','generic_name','Synthetic substance','brand_name',null,'schedule','II','concentration','10 mg/mL','concentration_source','Synthetic label for rollback','classification_source','Synthetic source for rollback','configuration_note','Draft only; register inactive'),'review_note','Synthetic rollback-only metadata review','attest_review',true));
select pg_temp.prove(is(prepare_controlled_draft_review(pg_temp.id('actor'),pg_temp.id('action'),'draft_configuration',(select value from controlled_fixture where key='request'))->>'state','prepared','Original draft preparation'));
insert into controlled_fixture values('saved',execute_controlled_draft_review(pg_temp.id('actor'),pg_temp.id('action')));
select pg_temp.prove(is(execute_controlled_draft_review(pg_temp.id('actor'),pg_temp.id('action')),(select value from controlled_fixture where key='saved'),'Same UUID exact saved receipt'));
select pg_temp.prove(is(read_controlled_draft_review(pg_temp.id('actor'),pg_temp.id('action'))->'receipt',(select value from controlled_fixture where key='saved'),'Owned read-only recovery'));
select pg_temp.prove(is(read_controlled_draft(pg_temp.id('entry'))->'entry',(select value->'entry'from controlled_fixture where key='saved'),'History preserves exact draft snapshot'));
select pg_temp.prove(is((select value#>>'{entry,state}'from controlled_fixture where key='saved'),'draft','Saved metadata is draft only'));
select pg_temp.prove(throws_ok($q$select prepare_controlled_draft_review(pg_temp.id('actor'),pg_temp.id('action'),'draft_configuration',(select jsonb_set(value,'{review_note}','"Changed original"')from controlled_fixture where key='request'))$q$,'23505',null,'Changed original UUID cannot overwrite work'));
select pg_temp.prove(is(cancel_controlled_draft_review(pg_temp.id('actor'),pg_temp.id('action'))->'receipt',(select value from controlled_fixture where key='saved'),'Cancel cannot erase committed draft'));
select pg_temp.prove(is(cancel_controlled_draft_review(pg_temp.id('actor'),pg_temp.id('missing_action'))->>'cancelled','true','Cancel-before-prepare persists tombstone'));
select pg_temp.prove(is(read_controlled_draft_review(pg_temp.id('actor'),pg_temp.id('missing_action'))->>'state','cancelled','Original missing preparation recovers cancelled'));
select pg_temp.prove(throws_ok($q$select prepare_controlled_draft_review(pg_temp.id('actor'),pg_temp.id('missing_action'),'draft_configuration',(select value from controlled_fixture where key='request'))$q$,'PT409',null,'Cancelled UUID cannot be revived'));
select pg_temp.prove(throws_ok($q$select prepare_controlled_draft_review(pg_temp.id('actor'),gen_random_uuid(),'activate',(select value from controlled_fixture where key='request'))$q$,'23514',null,'Physical activation is not a draft operation'));
set local timezone='America/Denver';
select pg_temp.prove(is(read_controlled_draft_review(pg_temp.id('actor'),pg_temp.id('action'))->'receipt',(select value from controlled_fixture where key='saved'),'Exact receipt survives caller timezone'));
reset role;
select pg_temp.prove(throws_ok($q$update controlled_draft_entries set state='active'where id=pg_temp.id('entry')$q$,'23514',null,'Draft state cannot be toggled active'));
select pg_temp.prove(throws_ok($q$update controlled_draft_actions set receipt='{}'where id=pg_temp.id('action')$q$,'23514',null,'Saved draft receipt immutable'));
select pg_temp.prove(is((select count(*)from controlled_draft_versions where entry_id=pg_temp.id('entry')),1::bigint,'Exactly one immutable draft version'));
select pg_temp.prove(is(jsonb_build_object('stock',(select count(*)from inventory_movements),'outbox',(select count(*)from communication_outbox),'invoices',(select count(*)from billing_invoices),'payments',(select count(*)from payment_provider_profiles)),(select value from controlled_fixture where key='baseline'),'Stock billing payments and communication unchanged'));
set constraints all immediate;
select jsonb_build_object('checks',current_setting('lrv.controlled_draft_checks')::integer,'provider_requests',0,'rollback_only',true)as proof;
rollback;
